"""逐批复核；只读回读与公开参考源码提交，不改平台测试或题库。"""
import argparse,ast,copy,datetime,hashlib,html,importlib.util,json,re,subprocess,sys,tempfile,time
from pathlib import Path
from unittest.mock import patch
sys.path[:0]=[str(Path.cwd()),str(Path.cwd()/'scripts')]
import judge,oj_submit
from gmyhf_authored_source import make
from fetch_gmyhf_testdata import DOWNLOAD_LINK,SAFE_FILENAME
from sync_gmyhf_followup import download
from tools.full_sweep import VALID_DRIVER
# 后台含sample0.in等名字，只改遍历排序，valid()本体与被检内容不变。
VALID_DRIVER=VALID_DRIVER.replace("key=lambda item: int(item.stem)","key=lambda item: item.name")
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def fields(page):return {label:re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]*>','',body))).strip() for label,body in re.findall(r'<dt>(.*?)</dt>\s*<dd>(.*?)</dd>',page,re.S) if label in ('描述','输入','输出','样例输入','样例输出')}
def write(path,doc):Path(path).write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n')
def run(batch,oracle_path,submit):
 spec=importlib.util.spec_from_file_location('batch_oracles',oracle_path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 entries={e['global_number']:e for e in json.loads(Path('collab/gmyhf-pending-triage.json').read_text())['entries']};catalog=json.loads(Path('data/openjudge/catalog.json').read_text())['problems'];output=Path(f'/tmp/gmyhf-batch{batch}-audit.json')
 if output.exists():result=json.loads(output.read_text())
 else:result={'batch':batch,'baseline':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'started_at':now(),'entries':[],'scope':'只读复核与自写独立算法参考源码提交；参考程序不含后台测试内容；不改平台测试、不激活数据或改valid()','sources':{p:sha(p) for p in ['judge.py','data/openjudge/catalog.json','data/openjudge/limits.json','collab/gmyhf-pending-triage.json']},'selfchecks':m.selfcheck()}
 session=oj_submit.Session().login();anonymous=oj_submit.Session()
 for n in m.NUMBERS:
  if any(r['global_number']==n and r.get('complete') and (not submit or 'platform' in r['checks']) for r in result['entries']):continue
  e=entries[n];base=Path('data/openjudge/tests/admin_download')/str(n);manifest=json.loads(Path('data/openjudge/tests/admin_download/manifest.json').read_text())['problems'][str(n)];files={f['filename']:f for f in manifest['files']};records=[]
  for name in sorted(files):
   if name.endswith('.in'):
    out=name[:-3]+'.out';assert out in files;records.append({'input':name,'output':out,'input_sha256':files[name]['sha256'],'output_sha256':files[out]['sha256']})
  assert len(records)*2==len(files)
  proof=m.reference(n) if hasattr(m,'reference') else make(oracle_path,m.SOLVERS[n].__name__);language=proof.get('language','python3');ref=Path(f'/tmp/gmyhf-authored-{n}.'+('cpp' if language=='cpp' else 'py'));ref.write_text(proof['source']);validator=Path(oracle_path);page=Path(f'data/openjudge/pages/practice__{n}.html')
  if not page.exists():page=Path(f'/tmp/gmyhf-public-{n}.html')
  row=next((r for r in result['entries'] if r['global_number']==n),None)
  if row is None:row={'global_number':n,'title':e['title'],'reference':str(ref),'reference_sha256':sha(ref),'validator':str(validator),'validator_sha256':sha(validator),'page':str(page),'page_sha256':sha(page),'checks':{}};result['entries'].append(row)
  try:
   assert row['reference_sha256']==sha(ref)
   assert sha(ref)==proof['sha256'];row['authored_reference']=proof
   for r in records:
    for k in ('input','output'):assert sha(base/r[k])==r[k+'_sha256'],(n,r[k],'snapshot drift')
   c=row['checks']
   if 'statement' not in c:
    old,new=fields(page.read_text()),fields(anonymous._get(oj_submit.HOST+f'/practice/{n}/'));assert len(old)==5;assert len(new)==5 or (not new and n in getattr(m,'UNAVAILABLE_NO_SUBMISSION',{}));c['statement']={'changed_fields':[k for k in old if old[k]!=new.get(k)],'available':len(new)==5,'checked_at':now()};write(output,result)
   if 'readback' not in c:
    admin=session._get(oj_submit.HOST+f'/admin/problems/edit/?id={n}');names=sorted({name for _,pid,name in DOWNLOAD_LINK.findall(admin) if int(pid)==n and SAFE_FILENAME.match(name)});expected={r[k]:r[k+'_sha256'] for r in records for k in ('input','output')};assert names==sorted(expected),(n,'file list drift');live=[]
    for name in names:
     value=hashlib.sha256(download(session,n,name)).hexdigest();live.append({'filename':name,'sha256':value,'matches':value==expected[name]});time.sleep(.1)
    c['readback']={'files':live,'checked_at':now()};write(output,result)
   if 'contract' not in c:
    checks=[{'input':r['input'],'issues':m.extra_contract(n,(base/r['input']).read_text(encoding='utf-8-sig'))} for r in records];c['contract']={'cases':len(records),'rejected':[r['input'] for r in checks if r['issues']],'definition':'原分类未提供_made参考和valid；按独立复算器extra_contract核题面约束，不声称通过既有valid。','checks':checks};write(output,result)
   if hasattr(m,'extra_contract') and 'extra_contract' not in c:
    c['extra_contract']={'definition':'按解码题面补足原valid未覆盖的语义范围；实现见独立复算器extra_contract','files':[{'input':r['input'],'issues':m.extra_contract(n,(base/r['input']).read_text(encoding='utf-8-sig'))} for r in records]};write(output,result)
   if hasattr(m,'decoded') and 'decoded_statement' not in c:
    c['decoded_statement']={'sha256':hashlib.sha256(m.decoded(n).encode()).hexdigest(),'procedure':'只对HTML数据节点或固定字符串做Base64及gzip解码，不执行JS'};write(output,result)
   if 'answers' not in c:
    samples=m.samples(n);assert samples or n in getattr(m,'NO_SAMPLES',{}),(n,'no samples')
    for given,want in samples:assert getattr(m,'compare',lambda n,a,b:a.split()==b.split())(n,m.SOLVERS[n](given),want),(n,'sample mismatch')
    checks=[]
    for r in records:
     issues=next(f['issues'] for f in c['contract']['checks'] if f['input']==r['input'])
     if issues:checks.append({**r,'matches':None,'not_compared_reason':'输入违反完整题面约束，不能把计算异常或未比较误作答案错误','oracle_ms':0});continue
     started=time.monotonic();got=m.SOLVERS[n]((base/r['input']).read_text(encoding='utf-8-sig'));want=(base/r['output']).read_text(encoding='utf-8-sig');checks.append({**r,'matches':getattr(m,'compare',lambda n,a,b:a.split()==b.split())(n,got,want),'oracle_ms':round((time.monotonic()-started)*1000)})
    c['answers']={'method':m.METHODS[n],'official_samples':len(samples),'files':checks};write(output,result)
   if 'local' not in c:
    item={'book':'practice','id':str(n),'global_number':n,'tests':True,'test_count':len(records),'test_cases':[]};item['test_cases']=[{'input':str((base/r['input']).resolve()),'output':str((base/r['output']).resolve())} for r in records]
    with patch.object(judge,'catalog_item',return_value=item):c['local']=judge.judge('practice',str(n),language,ref.read_text(),collect_case_times=True)
    for key in ('actual_output','expected_output','failing_input'):
     if key in c['local']:
      raw=str(c['local'].pop(key)).encode();c['local'][key+'_sha256']=hashlib.sha256(raw).hexdigest();c['local'][key+'_bytes']=len(raw)
    write(output,result)
   if not c['statement'].get('available',True):c['platform']={'final':'Not submitted','attempts':[],'reason':m.UNAVAILABLE_NO_SUBMISSION[n]}
   if submit and 'platform' not in c:
    attempts=row.setdefault('platform_attempts',[])
    for language in (('G++',) if ref.suffix=='.cpp' else ('Python3','PyPy3')):
     prior=next((a for a in attempts if a['language']==language),None)
     if prior is None:
      sid=session.submit(str(n),ref.read_text(),language);prior={'language':language,'solution_id':sid,'url':oj_submit.HOST+f'/practice/solution/{sid}/'};attempts.append(prior);write(output,result)
     if 'verdict' not in prior:prior.update(session.poll(prior['solution_id']));write(output,result)
     if prior['verdict']!='Time Limit Exceeded':break
    c['platform']={'final':attempts[-1]['verdict'],'attempts':attempts,'checked_at':now()};write(output,result)
   c['admission_boundary']={'original_reason':e['reason'],'preserve_exclusion':True,'reason':'原题号绑定或资源排除未改；答案核对通过不能自动激活'}
   row['passed']=not c['admission_boundary']['preserve_exclusion'] and not any(f['issues'] for f in c.get('extra_contract',{}).get('files',[])) and not c['statement']['changed_fields'] and all(f['matches'] for f in c['readback']['files']) and not c['contract']['rejected'] and all(f['matches'] for f in c['answers']['files']) and c['local']['status']=='Accepted' and c['local'].get('timing_audit',{}).get('status')=='passed' and c.get('platform',{}).get('final')=='Accepted';row['complete']=True;row.pop('error',None)
   print(n,'PASS' if row['passed'] else 'HOLD',c['local']['status'],c.get('platform',{}).get('final'),flush=True)
  except Exception as exc:row['error']=type(exc).__name__+': '+str(exc)[:180];print(n,'ERROR',row['error'],flush=True)
  write(output,result)
 result['finished_at']=now();result['procedures']=[{'filename':Path(p).name,'sha256':sha(p),'source':Path(p).read_text()} for p in ([__file__,oracle_path,'/tmp/gmyhf_authored_source.py']+(['/tmp/gmyhf_contract_diagnostic_driver.py'] if hasattr(m,'contract_diagnostic') else []))];write(output,result)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('batch',type=int);p.add_argument('oracle');p.add_argument('--submit',action='store_true');a=p.parse_args();run(a.batch,a.oracle,a.submit)

"""仅按独立复算器的函数依赖提取自写参考程序，不包含样例、后台输入或答案。"""
import ast,copy,hashlib
from pathlib import Path

def make(module_path,function_name):
 tree=ast.parse(Path(module_path).read_text());functions={n.name:n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))};needed=set()
 def visit(name):
  if name in needed:return
  needed.add(name)
  for node in ast.walk(functions[name]):
   if isinstance(node,ast.Name) and isinstance(node.ctx,ast.Load) and node.id in functions:visit(node.id)
 visit(function_name)
 body=[copy.deepcopy(n) for n in tree.body if isinstance(n,(ast.Import,ast.ImportFrom)) or isinstance(n,ast.FunctionDef) and n.name in needed]
 body+=ast.parse(f'import sys\nsys.stdout.write({function_name}(sys.stdin.read())+"\\n")').body
 source=ast.unparse(ast.fix_missing_locations(ast.Module(body=body,type_ignores=[])))+'\n'
 return {'source':source,'sha256':hashlib.sha256(source.encode()).hexdigest(),'procedure':'从自写独立复算器按AST函数依赖闭包提取，保留导入并添加标准输入输出入口；不读取或拼接任何后台测试内容'}

"""五道仍公开可见的未映射题：独立算法与穷举锚点。"""
import itertools,random,heapq
from collections import Counter,deque
NUMBERS=[31197,31198,31239,31240,31241]
def police(s):
 v=list(map(int,s.split()));balance=low=0
 for x in v[1:]:balance+=x;low=min(low,balance)
 return str(-low)
def matrix(s):
 a=list(map(int,s.split()));assert len(a)==25 and a.count(1)==1 and all(x in (0,1) for x in a);i=a.index(1);return str(abs(i//5-2)+abs(i%5-2))
def single_pair(a):
 n=len(a);INF=10**30;apple=[];peach=[];active=[];both=[]
 for i,(x,y,z) in enumerate(a):
  apple.append((y+z+1 if x else INF,i));peach.append((x+z+1 if y else INF,i));active.append((z+1 if x+y else INF,i));both.append((max(x,y)+z+1 if x and y else INF,i))
 apple.sort();peach.sort();active.sort();best=INF
 for cost,i in apple:
  other=next((v for v,j in peach[:2] if j!=i),INF);best=min(best,cost+other)
 for cost,i in both:best=min(best,cost+next((v for v,j in active[:2] if j!=i),INF))
 return best if best<INF else -1
def three_flavors(s):
 v=list(map(int,s.split()));n=v[0];assert len(v)==1+3*n;return str(single_pair([v[i:i+3] for i in range(1,len(v),3)]))
def two_shapes(s):
 v=list(map(int,s.split()));m,x,y=v[:3];assert len(v)==3+2*m;a=[v[3:3+m],v[3+m:]];return str(single_pair([(r[x-1],r[y-1],sum(r)-r[x-1]-r[y-1]) for r in a]))
def bad_capacities(a,edges):
 n=len(a);m=len(a[0]);adj=[0]*m
 for u,v in edges:adj[u]|=1<<v;adj[v]|=1<<u
 caps=set();available=[sum((1<<j) for j,x in enumerate(row) if x) for row in a];free=sum((1<<j) for j in range(m) if not adj[j])
 # 无跨形状搭配时，已摸到口味诱导图的每个非平凡连通块只能属于同一形状。
 # 孤立口味可分布在所有形状；枚举口味子集及各非平凡块所属形状给出全部坏情形上界。
 for mask in range(1<<m):
  if mask&free!=free:continue
  unseen=mask;isolated=0;components=[]
  while unseen:
   bit=unseen&-unseen;component=0;todo=bit
   while todo:
    b=todo&-todo;todo^=b;u=b.bit_length()-1;component|=b;unseen&=~b;todo|=adj[u]&unseen
   if component&(component-1):components.append(component)
   else:isolated|=component
  base=tuple(sum(row[j] for j in range(m) if isolated>>j&1) for row in a)
  weights=[tuple(sum(row[j] for j in range(m) if component>>j&1) for row in a) for component in components]
  for assignment in itertools.product(range(n),repeat=len(weights)):
   c=list(base);supports=[isolated&avail for avail in available]
   for component,w,i in zip(components,weights,assignment):c[i]+=w[i];supports[i]|=component&available[i]
   prefix=[0]
   for support in supports:prefix.append(prefix[-1]|support)
   suffix=[0]*(n+1)
   for i in range(n-1,-1,-1):suffix[i]=suffix[i+1]|supports[i]
   maximal=True
   for i in range(n):
    missing=available[i]&~supports[i];outside=prefix[i]|suffix[i+1]
    while missing:
     bit=missing&-missing;missing^=bit;j=bit.bit_length()-1
     if not adj[j]&outside:maximal=False;break
    if not maximal:break
   # 可增加任一口味且仍无跨形状搭配，则该坏容量盒被其扩展盒覆盖，可安全删除。
   if maximal:caps.add(tuple(c))
 return sorted(caps,key=lambda x:(sum(x),x))
def capacity_index(caps,n):
 # 对坏容量盒建立支配查询树；每结点按各维上下界剪枝，仍返回最先的支配盒。
 def build(ids):
